CREATE TABLE IF NOT EXISTS system_intelligence_signals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,signal_type TEXT NOT NULL,source TEXT,entity_type TEXT,entity_id UUID,severity TEXT DEFAULT 'info',payload JSONB NOT NULL DEFAULT '{}'::jsonb,observed_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS system_intelligence_insights (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,domain TEXT NOT NULL,title TEXT NOT NULL,summary TEXT,confidence NUMERIC(6,2),evidence JSONB NOT NULL DEFAULT '{}'::jsonb,status TEXT NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS system_intelligence_actions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,domain TEXT NOT NULL,insight_id UUID,action TEXT NOT NULL,priority INTEGER DEFAULT 50,status TEXT NOT NULL DEFAULT 'proposed',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_int_signal_user ON system_intelligence_signals(user_id,signal_type,observed_at DESC);
CREATE INDEX IF NOT EXISTS idx_int_insight_user ON system_intelligence_insights(user_id,domain,created_at DESC);